export type GarageRates = {
  vatRate: number;
  vatRates: number[];
  partsVatRate: number;
  labourVatRate: number;
  consumablesVatRate: number;
  vatAccountingBasis: 'unconfirmed' | 'invoice' | 'cash';
  labourRate: number;
  consumablesDefault: number;
  wasteDefault: number;
  quoteCustomerNote: string;
  jobCardCustomerNote: string;
  invoiceCustomerNote: string;
};

export const garageRatesKey = 'aa-garage-rates-v1';
export const readGarageRates = (): GarageRates => {
  try {
    const stored = JSON.parse(localStorage.getItem(garageRatesKey) || '{}');
    const consumablesMigrationKey = 'aa-garage-consumables-default-12-v1';
    if (!localStorage.getItem(consumablesMigrationKey)) {
      stored.consumablesDefault = 12;
      localStorage.setItem(garageRatesKey, JSON.stringify(stored));
      localStorage.setItem(consumablesMigrationKey, 'true');
    }
    const vatRate = Number(stored.vatRate ?? 13.5);
    const vatRates = Array.from(new Set([vatRate, ...(Array.isArray(stored.vatRates) ? stored.vatRates.map(Number) : [13.5, 23])])).filter(value => Number.isFinite(value) && value >= 0);
    return { labourRate: 100, consumablesDefault: 12, wasteDefault: 0, quoteCustomerNote: '', jobCardCustomerNote:'', invoiceCustomerNote:'', partsVatRate:23, labourVatRate:13.5, consumablesVatRate:13.5, vatAccountingBasis:'unconfirmed', ...stored, jobCardCustomerNote:localStorage.getItem('aa-garage-job-card-customer-note')??stored.jobCardCustomerNote??'', invoiceCustomerNote:localStorage.getItem('aa-garage-invoice-customer-note')??stored.invoiceCustomerNote??'', vatRate, vatRates };
  } catch {
    return { vatRate: 13.5, vatRates: [13.5, 23], partsVatRate:23, labourVatRate:13.5, consumablesVatRate:13.5, vatAccountingBasis:'unconfirmed', labourRate: 100, consumablesDefault: 12, wasteDefault: 0, quoteCustomerNote: '', jobCardCustomerNote:'', invoiceCustomerNote:'' };
  }
};

type SavedCustomJob = { id: string; name: string; hours: number; labourRate: number; parts: string[]; createdAt: string };
type ChecklistCheck={id:string;name:string;phrases:string[]};
type ChecklistCategory={id:string;name:string;checks:ChecklistCheck[]};
type ChecklistTemplate={id:string;name:string;categories:ChecklistCategory[];createdAt:string};
const checklistKey='aa-garage-checklist-templates';
const readChecklistTemplates=():ChecklistTemplate[]=>{try{const value=JSON.parse(localStorage.getItem(checklistKey)||'[]');return Array.isArray(value)?value:[]}catch{return[]}};
const readCustomJobs = (): SavedCustomJob[] => {
  try { return JSON.parse(localStorage.getItem('aa-garage-custom-jobs') || '[]'); }
  catch { return []; }
};

const readVatReport = (rates: GarageRates) => {
  const invoices:any[]=[];
  for(let index=0;index<localStorage.length;index++){
    const key=localStorage.key(index);
    if(!key?.startsWith('aa-garage-invoices-'))continue;
    try{const records=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(records))invoices.push(...records)}catch{}
  }
  const unique=Array.from(new Map(invoices.map(invoice=>[invoice.id,invoice])).values());
  const byRate:Record<string,{net:number;vat:number;gross:number;receivedVat:number}>={};
  const add=(net:number,rate:number,paidRatio:number)=>{const vat=net*rate/100,key=String(rate),row=byRate[key]||{net:0,vat:0,gross:0,receivedVat:0};row.net+=net;row.vat+=vat;row.gross+=net+vat;row.receivedVat+=vat*paidRatio;byRate[key]=row};
  unique.forEach(invoice=>{const grossLines=(invoice.jobs||[]).flatMap((job:any)=>[{net:Number(job.labourHours||0)*Number(job.labourRate||0),rate:Number(job.labourVatRate??rates.labourVatRate)},...(job.parts||[]).map((part:any)=>({net:Number(part.quantity||0)*Number(part.price||0),rate:Number(part.vatRate??rates.partsVatRate)}))]);if(Number(invoice.consumablesWaste||0)>0)grossLines.push({net:Number(invoice.consumablesWaste),rate:Number(invoice.consumablesVatRate??rates.consumablesVatRate)});const gross=grossLines.reduce((sum:any,line:any)=>sum+line.net*(1+line.rate/100),0),paid=Math.max(0,Math.min(gross,Number(invoice.amountPaid??(invoice.payments||[]).reduce((sum:number,payment:any)=>sum+Number(payment.amount||0),0)))),ratio=gross>0?paid/gross:0;grossLines.forEach((line:any)=>add(line.net,line.rate,ratio))});
  const payments=unique.flatMap(invoice=>(invoice.payments||[]).map((payment:any,index:number)=>({paymentId:payment.id||'',invoiceId:invoice.id,customer:invoice.customer||'Customer not recorded',date:payment.date||'',method:payment.method||'Method not recorded',amount:Number(payment.amount||0),key:`${invoice.id}-${index}`}))).map((payment,index)=>({...payment,paymentId:payment.paymentId||`PAY-${String(index+1).padStart(5,'0')}`}));
  return {invoices:unique.length,rows:Object.entries(byRate).sort((a,b)=>Number(a[0])-Number(b[0])),invoiceVat:Object.values(byRate).reduce((sum,row)=>sum+row.vat,0),receivedVat:Object.values(byRate).reduce((sum,row)=>sum+row.receivedVat,0),payments};
};

const installProtectedGarageEdits = () => {
  if (typeof document === 'undefined') return;
  const install = () => document.querySelectorAll<HTMLElement>('.universalWidget:has(.gms) > .universalWidgetTools').forEach(tools => {
    if (tools.querySelector('[data-action="garage-protected-edit"]')) return;
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.action = 'garage-protected-edit';
    button.title = 'Edit protected garage settings';
    button.setAttribute('aria-label', 'Edit protected garage settings');
    button.textContent = '✎';
    button.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      if ((sessionStorage.getItem('aa-role') || 'owner') !== 'owner') {
        alert('Only the main account can edit this.');
        return;
      }
      window.dispatchEvent(new CustomEvent('aa-navigate', { detail: { biz: 'motors', page: 'garage-settings' } }));
    });
    tools.appendChild(button);
  });
  new MutationObserver(install).observe(document.documentElement, { childList: true, subtree: true });
  queueMicrotask(install);
};
installProtectedGarageEdits();

